#!/usr/bin/env python3
"""Turns assets/fonts/dbyte_1x.png (DINOBYTE by mby, 6 by 8 cells, CC BY 4.0, unmodified) into odin/game/font_data.odin.

Each glyph row is a u8 bit mask, bit x = pixel in column x. ASCII 32..127.
"""
import os
from PIL import Image

root = os.path.join(os.path.dirname(__file__), "..")
im = Image.open(os.path.join(root, "assets", "fonts", "dbyte_1x.png")).convert("RGBA")
lines = [
    "// Generated by tools/gen_fonts.py from assets/fonts/dbyte_1x.png (DINOBYTE by mby, CC BY 4.0). Do not edit.",
    "package game",
    "",
    "FONT_WIDTH :: 6",
    "FONT_HEIGHT :: 8",
    "FONT_FIRST :: 32",
    "",
    "FONT := [96][8]u8{",
]
for code in range(32, 128):
    sx, sy = code % 16 * 6, code // 16 * 8
    rows = []
    for y in range(8):
        bits = 0
        for x in range(6):
            if im.getpixel((sx + x, sy + y))[3] > 0:
                bits |= 1 << x
        rows.append(bits)
    lines.append("\t{" + ", ".join(str(v) for v in rows) + "}, // " + repr(chr(code)))
lines.append("}")
out = os.path.join(root, "odin", "game", "font_data.odin")
with open(out, "w") as f:
    f.write("\n".join(lines) + "\n")
print("wrote", out)
